import { Injectable, signal } from '@angular/core';

export type MessageKind = 'success' | 'error';

export interface UiMessage {
  id: number;
  kind: MessageKind;
  text: string;
}

/** Shows success/error messages, closing each one after 5 seconds like the GWT MessageCloseDelay.DEFAULT. */
@Injectable({ providedIn: 'root' })
export class MessageService {
  readonly messages = signal<UiMessage[]>([]);

  private nextId = 1;
  private static readonly CLOSE_DELAY_MS = 5000;

  success(text: string): void {
    this.add('success', text);
  }

  error(text: string): void {
    this.add('error', text);
  }

  dismiss(id: number): void {
    this.messages.update((list) => list.filter((message) => message.id !== id));
  }

  private add(kind: MessageKind, text: string): void {
    const id = this.nextId++;
    this.messages.update((list) => [...list, { id, kind, text }]);
    setTimeout(() => this.dismiss(id), MessageService.CLOSE_DELAY_MS);
  }
}
EOF
