import { FormsModule } from '@angular/forms';

import { ApiService } from '../core/api.service';
import { MessageService } from '../core/message.service';
import { Manufacturer } from '../models';

/** Create/edit popup for a manufacturer (GWT EditManufacturerView). */
@Component({
  selector: 'app-edit-manufacturer',
  standalone: true,
  imports: [FormsModule],
  template: `
    <div class="overlay">
      <div id="gwt-debug-manufacturer-editor" class="popup">
        <div class="form-row">
          <label>
            Name:
            <input id="gwt-debug-manufacturer-input" name="name" type="text" [(ngModel)]="name" />
          </label>
        </div>
        <div class="form-row">
          <button id="gwt-debug-manufacturer-save" type="button" (click)="save()">Save</button>
          <button id="gwt-debug-manufacturer-close" type="button" (click)="closed.emit()">Close</button>
        </div>
      </div>
    </div>
  `,
})
export class EditManufacturerComponent {
  @Input({ required: true }) manufacturer!: Manufacturer;
  @Output() readonly saved = new EventEmitter<Manufacturer>();
  @Output() readonly closed = new EventEmitter<void>();

  protected name = '';

  private readonly api = inject(ApiService);
  private readonly messages = inject(MessageService);

  ngOnInit(): void {
    this.name = this.manufacturer.name;
  }

  protected save(): void {
    const toSave: Manufacturer = { ...this.manufacturer, name: this.name };
    this.api.saveManufacturer(toSave).subscribe({
      next: (saved) => {
        this.messages.success('The manufacturer has been saved.');
        this.saved.emit(saved);
      },
      error: () => this.messages.error('The manufacturer could not be saved.'),
    });
  }
}
