import { Component, OnInit, inject } from '@angular/core';

import { ApiService } from '../core/api.service';
import { MessageService } from '../core/message.service';
import { Manufacturer } from '../models';
import { EditManufacturerComponent } from './edit-manufacturer.component';

@Component({
  selector: 'app-manufacturer-page',
  standalone: true,
  imports: [EditManufacturerComponent],
  template: `
    <div class="page-title">
      <h2>Manufacturers</h2>
      <div>
        <button id="gwt-debug-create-manufacturer" type="button" class="add-action" (click)="create()">
          Add
        </button>
      </div>
    </div>

    <div class="table-wrapper">
      <table id="gwt-debug-manufacturers" class="data-table">
        <thead>
          <tr>
            <th>ID</th>
            <th>Name</th>
            <th>Edit</th>
            <th>Delete</th>
          </tr>
        </thead>
        <tbody>
          @for (manufacturer of manufacturers; track manufacturer.id) {
            <tr>
              <td>{{ manufacturer.id }}</td>
              <td>{{ manufacturer.name }}</td>
              <td><button type="button" (click)="edit(manufacturer)">Edit</button></td>
              <td><button type="button" (click)="remove(manufacturer)">Delete</button></td>
            </tr>
          }
        </tbody>
      </table>
    </div>

    @if (editing) {
      <app-edit-manufacturer
        [manufacturer]="editing"
        (saved)="onSaved($event)"
        (closed)="editing = null" />
    }
  `,
})
export class ManufacturerPageComponent implements OnInit {
  protected manufacturers: Manufacturer[] = [];
  /** Manufacturer being created (new, no id) or edited; null when the popup is closed. */
  protected editing: Manufacturer | null = null;

  private readonly api = inject(ApiService);
  private readonly messages = inject(MessageService);

  ngOnInit(): void {
    this.api.getManufacturers().subscribe({
      next: (manufacturers) => (this.manufacturers = manufacturers),
      error: () => this.messages.error('The manufacturers could not be loaded.'),
    });
  }

  protected create(): void {
    this.editing = { name: '' };
  }

  protected edit(manufacturer: Manufacturer): void {
    this.editing = { ...manufacturer };
  }

  protected onSaved(saved: Manufacturer): void {
    const index = this.manufacturers.findIndex((m) => m.id != null && m.id === saved.id);
    if (index >= 0) {
      this.manufacturers[index] = saved;
      this.manufacturers = [...this.manufacturers];
    } else {
      this.manufacturers = [...this.manufacturers, saved];
    }
    this.editing = null;
  }

  protected remove(manufacturer: Manufacturer): void {
    if (!window.confirm(`Are you sure you want to delete ${manufacturer.name}?`)) {
      return;
    }
    this.api.deleteManufacturer(manufacturer.id as number).subscribe({
      next: () => {
        this.manufacturers = this.manufacturers.filter((m) => m.id !== manufacturer.id);
      },
      error: () => this.messages.error('The manufacturer could not be deleted.'),
    });
  }
}
