import { FormsModule } from '@angular/forms';

import { ApiService } from '../core/api.service';
import { MessageService } from '../core/message.service';
import { Car, Rating, carLabel } from '../models';

/** Create form for a rating: pick a car, enter a rating, Save (GWT EditRatingView). */
@Component({
  selector: 'app-edit-rating',
  standalone: true,
  imports: [FormsModule],
  template: `
    <div class="overlay">
      <div class="popup">
        <div class="form-row">
          <label>
            Car:
            <select id="gwt-debug-rating-car" name="car" [(ngModel)]="selectedCar">
              @for (car of cars; track car.id) {
                <option [ngValue]="car">{{ carName(car) }}</option>
              }
            </select>
          </label>
        </div>
        <div class="form-row">
          <label>
            Your rating:
            <input
              id="gwt-debug-ratingInput"
              name="rating"
              type="number"
              step="1"
              maxlength="3"
              [(ngModel)]="ratingValue" />
          </label>
        </div>
        <div class="form-row">
          <button
            id="gwt-debug-ratingSave"
            type="button"
            [disabled]="!selectedCar || ratingValue === null"
            (click)="save()">
            Save
          </button>
          <button id="gwt-debug-rating-close" type="button" (click)="closed.emit()">Close</button>
        </div>
      </div>
    </div>
  `,
})
export class EditRatingComponent implements OnInit {
  @Output() readonly saved = new EventEmitter<Rating>();
  @Output() readonly closed = new EventEmitter<void>();

  protected cars: Car[] = [];
  protected selectedCar: Car | null = null;
  protected ratingValue: number | null = null;

  private readonly api = inject(ApiService);
  private readonly messages = inject(MessageService);

  ngOnInit(): void {
    this.api.getCars().subscribe({
      next: (cars) => {
        this.cars = cars;
        this.selectedCar = cars[0] ?? null;
      },
      error: () => this.messages.error('The cars could not be loaded.'),
    });
  }

  protected carName(car: Car): string {
    return carLabel(car);
  }

  protected save(): void {
    if (!this.selectedCar || this.ratingValue === null) {
      return;
    }
    const car = this.selectedCar;
    const toSave: Rating = { rating: this.ratingValue, car };
    this.api.saveRating(toSave).subscribe({
      next: (saved) => {
        this.messages.success('The rating has been saved.');
        this.saved.emit({ ...saved, car: saved.car ?? car });
      },
      error: () => this.messages.error('The rating could not be saved.'),
    });
  }
}
