  protected creating = false;

  private readonly api = inject(ApiService);
  private readonly messages = inject(MessageService);

  ngOnInit(): void {
    this.api.getRatings().subscribe({
      next: (ratings) => (this.ratings = ratings),
      error: () => this.messages.error('The ratings could not be loaded.'),
    });
  }

  protected carName(rating: Rating): string {
    return carLabel(rating.car);
  }

  protected onSaved(saved: Rating): void {
    this.ratings = [...this.ratings, saved];
    this.creating = false;
  }

  protected remove(rating: Rating): void {
    if (!window.confirm(`Are you sure you want to delete ${this.carName(rating)}?`)) {
      return;
    }
    this.api.deleteRating(rating.id as number).subscribe({
      next: () => {
        this.ratings = this.ratings.filter((r) => r.id !== rating.id);
      },
      error: () => this.messages.error('The rating could not be deleted.'),
    });
  }
}
