// Drives headless Chromium over CDP, replaying the e2e feature scenarios with the
// same element ids/xpaths as the Selenium page objects.
const WebSocket = require('/work/node_modules/ws');
const http = require('http');
const { spawn } = require('child_process');

const BASE = process.env.BASE || 'http://localhost:8888/ng/';
const sleep = (ms) => new Promise((r) => setTimeout(r, ms));
const results = [];

function getJson(url) {
  return new Promise((res, rej) => http.get(url, (r) => { let d = ''; r.on('data', (c) => (d += c)); r.on('end', () => res(JSON.parse(d))); }).on('error', rej));
}

async function main() {
  const chrome = spawn('/usr/bin/chromium', ['--headless=new', '--no-sandbox', '--disable-gpu', '--remote-debugging-port=9333',
    '--user-data-dir=/tmp/e2e-check/profile', '--window-size=1280,900', 'about:blank'], { stdio: 'ignore' });
  let targets;
  for (let i = 0; i < 50; i++) { try { targets = await getJson('http://127.0.0.1:9333/json'); break; } catch { await sleep(200); } }
  const page = targets.find((t) => t.type === 'page');
  const ws = new WebSocket(page.webSocketDebuggerUrl);
  await new Promise((r) => ws.on('open', r));
  let id = 0; const pending = new Map();
  ws.on('message', (m) => { const msg = JSON.parse(m); if (msg.id && pending.has(msg.id)) { pending.get(msg.id)(msg); pending.delete(msg.id); } });
  const send = (method, params = {}) => new Promise((r) => { const i = ++id; pending.set(i, r); ws.send(JSON.stringify({ id: i, method, params })); });
  const ev = async (expr) => {
    const r = await send('Runtime.evaluate', { expression: expr, awaitPromise: true, returnByValue: true });
    if (r.result.exceptionDetails) throw new Error('JS error: ' + JSON.stringify(r.result.exceptionDetails).slice(0, 300));
    return r.result.result.value;
  };
  const waitFor = async (expr, what, t = 8000) => {
    const end = Date.now() + t;
    while (Date.now() < end) { if (await ev(expr)) return; await sleep(100); }
    throw new Error('timeout waiting for ' + what);
  };
  const click = async (sel) => { await waitFor(`!!document.querySelector(${JSON.stringify(sel)})&&!document.querySelector(${JSON.stringify(sel)}).disabled`, 'clickable ' + sel); await ev(`document.querySelector(${JSON.stringify(sel)}).click()`); };
  const typeIn = async (sel, text, clear = true) => {
    await waitFor(`!!document.querySelector(${JSON.stringify(sel)})`, 'input ' + sel);
    await ev(`(()=>{const e=document.querySelector(${JSON.stringify(sel)}); e.focus(); e.select();})()`);
    if (clear) await send('Input.dispatchKeyEvent', { type: 'keyDown', key: 'Backspace', code: 'Backspace', windowsVirtualKeyCode: 8 });
    if (clear) await send('Input.dispatchKeyEvent', { type: 'keyUp', key: 'Backspace', code: 'Backspace', windowsVirtualKeyCode: 8 });
    await send('Input.insertText', { text });
  };
  const rowCount = (table) => ev(`document.querySelectorAll('#gwt-debug-${table} > tbody:first-of-type > tr').length`);
  const cell = (table, row, col) => ev(`(()=>{const t=document.querySelector('#gwt-debug-${table}');const idx=[...t.querySelectorAll('thead th')].findIndex(th=>th.textContent.trim()===${JSON.stringify(col)})+1;return t.querySelector('tbody:first-of-type > tr:nth-child(${row}) > td:nth-child('+idx+')').textContent.trim();})()`);
  const lastCell = (table, row, col) => cell(table, row, col);
  const checkpoint = async (name, fn) => {
    try { await fn(); results.push(['PASS', name]); console.log('PASS', name); }
    catch (e) { results.push(['FAIL', name, e.message]); console.log('FAIL', name, e.message); }
  };
  const assert = (cond, msg) => { if (!cond) throw new Error(msg); };
  const nav = async (token) => { await send('Page.navigate', { url: BASE + '#' + token }); await waitFor(`!!document.querySelector('#gwt-debug-menubar')`, 'menubar'); await sleep(300); };
  await send('Page.enable'); await send('Runtime.enable'); await send('Input.setIgnoreInputEvents', { ignore: false });
  // Dismiss nothing; test overrides confirm as the Selenium BasePage does.
  const overrideConfirm = () => ev(`window.confirm = function(){return true;}`);

  await checkpoint('menubar links contain history tokens', async () => {
    await nav('manufacturer');
    const hrefs = await ev(`[...document.querySelectorAll('#gwt-debug-menubar a')].map(a=>a.getAttribute('href'))`);
    console.log('   hrefs', JSON.stringify(hrefs));
    for (const t of ['manufacturer', 'rating', 'report']) assert(hrefs.some((h) => h.includes(t)), 'no link for ' + t);
    // Navigate via the menubar like HeaderWidgetPage.navigateTo
    await ev(`document.querySelector('#gwt-debug-menubar a[href*="rating"]').click()`);
    await waitFor(`location.hash === '#rating'`, 'hash #rating');
    await ev(`document.querySelector('#gwt-debug-menubar a[href*="report"]').click()`);
    await waitFor(`location.hash === '#report'`, 'hash #report');
    await waitFor(`!!document.querySelector('#gwt-debug-reports')`, 'report table');
    await ev(`document.querySelector('#gwt-debug-menubar a[href*="manufacturer"]').click()`);
    await waitFor(`location.hash === '#manufacturer'`, 'hash #manufacturer');
  });

  await overrideConfirm();
  await checkpoint('Manufacturers: create shows editor', async () => {
    await nav('manufacturer');
    await waitFor(`!!document.querySelector('#gwt-debug-manufacturers')`, 'table');
    await click('#gwt-debug-create-manufacturer');
    await waitFor(`!!document.querySelector('#gwt-debug-manufacturer-editor')`, 'editor');
    await ev(`document.querySelector('#gwt-debug-manufacturer-close').click()`);
  });

  await checkpoint('Manufacturers: close keeps table unchanged', async () => {
    await nav('manufacturer');
    await waitFor(`!!document.querySelector('#gwt-debug-manufacturers tbody tr')`, 'rows');
    const before = await rowCount('manufacturers');
    await click('#gwt-debug-create-manufacturer');
    await typeIn('#gwt-debug-manufacturer-input', 'Ford', false);
    await click('#gwt-debug-manufacturer-close');
    await sleep(200);
    assert(await rowCount('manufacturers') === before, 'row count changed');
    assert(!(await ev(`!!document.querySelector('#gwt-debug-manufacturer-editor')`)), 'editor still open');
  });

  let beforeCreate;
  await checkpoint('Manufacturers: save creates Plymouth at the end', async () => {
    await nav('manufacturer');
    await waitFor(`!!document.querySelector('#gwt-debug-manufacturers tbody tr')`, 'rows');
    beforeCreate = await rowCount('manufacturers');
    await click('#gwt-debug-create-manufacturer');
    await typeIn('#gwt-debug-manufacturer-input', 'Plymouth', false);
    await click('#gwt-debug-manufacturer-save');
    await waitFor(`[...document.querySelectorAll('#gwt-debug-successMessage span:first-child')].some(s=>s.textContent.includes('saved'))`, 'success message');
    await waitFor(`document.querySelectorAll('#gwt-debug-manufacturers > tbody:first-of-type > tr').length > ${beforeCreate}`, 'row incremented');
    const last = await lastCell('manufacturers', beforeCreate + 1, 'Name');
    assert(last === 'Plymouth', 'last manufacturer is ' + last);
  });

  await checkpoint('Manufacturers: edit first row to Ford', async () => {
    await nav('manufacturer');
    await waitFor(`!!document.querySelector('#gwt-debug-manufacturers tbody tr')`, 'rows');
    await ev(`document.querySelector('#gwt-debug-manufacturers tbody td:nth-last-child(2) button').click()`);
    await waitFor(`!!document.querySelector('#gwt-debug-manufacturer-editor')`, 'editor');
    await typeIn('#gwt-debug-manufacturer-input', 'Ford');
    await click('#gwt-debug-manufacturer-save');
    await waitFor(`[...document.querySelectorAll('#gwt-debug-successMessage span:first-child')].some(s=>s.textContent.includes('saved'))`, 'success message');
    await sleep(200);
    assert((await cell('manufacturers', 1, 'Name')) === 'Ford', 'first is not Ford');
  });

  await checkpoint('Manufacturers: delete first row', async () => {
    await nav('manufacturer');
    await waitFor(`!!document.querySelector('#gwt-debug-manufacturers tbody tr')`, 'rows');
    const before = await rowCount('manufacturers');
    await ev(`document.querySelector('#gwt-debug-manufacturers tbody td:last-child button').click()`);
    await waitFor(`document.querySelectorAll('#gwt-debug-manufacturers > tbody:first-of-type > tr').length === ${before - 1}`, 'row removed');
  });

  await checkpoint('Ratings: add a rating', async () => {
    await nav('rating');
    await waitFor(`!!document.querySelector('#gwt-debug-ratings tbody tr')`, 'rating rows');
    const before = await rowCount('ratings');
    await click('#gwt-debug-ratingCreate');
    await waitFor(`!!document.querySelector('#gwt-debug-ratingInput')`, 'rating input');
    await typeIn('#gwt-debug-ratingInput', '10', false);
    await click('#gwt-debug-ratingSave');
    await waitFor(`!!document.querySelector('#gwt-debug-successMessage')`, 'success');
    await waitFor(`document.querySelectorAll('#gwt-debug-ratings > tbody:first-of-type > tr').length === ${before + 1}`, 'row added');
    await waitFor(`!document.querySelector('#gwt-debug-ratingSave')`, 'popup closed');
  });

  await checkpoint('Ratings: delete first row', async () => {
    await nav('rating');
    await waitFor(`!!document.querySelector('#gwt-debug-ratings tbody tr')`, 'rating rows');
    const before = await rowCount('ratings');
    await ev(`document.querySelector('#gwt-debug-ratings tbody td:last-child button').click()`);
    await waitFor(`document.querySelectorAll('#gwt-debug-ratings > tbody:first-of-type > tr').length === ${before - 1}`, 'rating removed');
  });

  await checkpoint('Reports: averages match ratings table', async () => {
    await nav('rating');
    await waitFor(`!!document.querySelector('#gwt-debug-ratings tbody tr')`, 'rating rows');
    const n = await rowCount('ratings');
    const sums = {};
    for (let r = 1; r <= n; r++) {
      const car = await cell('ratings', r, 'Car');
      const rating = Number(await cell('ratings', r, 'Rating'));
      const m = car.substring(0, car.indexOf('/'));
      sums[m] = sums[m] || { s: 0, c: 0 };
      sums[m].s += rating; sums[m].c++;
    }
    await nav('report');
    await waitFor(`!!document.querySelector('#gwt-debug-reports tbody tr')`, 'report rows');
    const rn = await rowCount('reports');
    assert(rn > 0, 'no report rows');
    for (let r = 1; r <= rn; r++) {
      const m = await cell('reports', r, 'Manufacturer');
      const avg = Number(await cell('reports', r, 'Rating'));
      assert(sums[m], 'manufacturer ' + m + ' not in ratings');
      assert(Math.abs(avg - sums[m].s / sums[m].c) < 0.001, `avg mismatch for ${m}: ${avg} vs ${sums[m].s / sums[m].c}`);
    }
  });

  ws.close(); chrome.kill();
  const failed = results.filter((r) => r[0] === 'FAIL');
  console.log(`\n${results.length - failed.length}/${results.length} passed`);
  process.exit(failed.length ? 1 : 0);
}
main().catch((e) => { console.error('ERROR', e); process.exit(2); });
