const WebSocket = require('/work/node_modules/ws');
const http = require('http'); const { spawn } = require('child_process'); const fs = require('fs');
const sleep = (ms) => new Promise((r) => setTimeout(r, ms));
(async () => {
  const chrome = spawn('/usr/bin/chromium', ['--headless=new','--no-sandbox','--disable-gpu','--window-size=1100,600','--remote-debugging-port=9335','--user-data-dir=/tmp/e2e-check/profile3','about:blank'], { stdio: 'ignore' });
  let t; for (let i=0;i<50;i++){ try { t = await new Promise((res,rej)=>http.get('http://127.0.0.1:9335/json',r=>{let d='';r.on('data',c=>d+=c);r.on('end',()=>res(JSON.parse(d)));}).on('error',rej)); break; } catch { await sleep(200); } }
  const ws = new WebSocket(t.find(x=>x.type==='page').webSocketDebuggerUrl); await new Promise(r=>ws.on('open',r));
  let id=0; const p=new Map(); ws.on('message',m=>{const x=JSON.parse(m); if(p.has(x.id)){p.get(x.id)(x);p.delete(x.id);}});
  const send=(method,params={})=>new Promise(r=>{const i=++id;p.set(i,r);ws.send(JSON.stringify({id:i,method,params}));});
  const ev=async e=>{const r=await send('Runtime.evaluate',{expression:e,awaitPromise:true,returnByValue:true});return r.result.result.value;};
  await send('Page.enable');
  await send('Page.navigate',{url:'http://localhost:8888/ng/'}); await sleep(3000);
  console.log('root hash:', await ev('location.hash'), '| rows:', await ev('document.querySelectorAll("#gwt-debug-manufacturers tbody tr").length'));
  await send('Page.navigate',{url:'http://localhost:8888/ng/#rating'}); await sleep(2000);
  await send('Page.navigate',{url:'http://localhost:8888/ng/#rating'}); await sleep(1000);
  await ev('document.querySelector("#gwt-debug-ratingCreate").click()'); await sleep(1000);
  const shot = await send('Page.captureScreenshot',{format:'png'});
  fs.writeFileSync('/tmp/e2e-check/rating-popup.png', Buffer.from(shot.result.data,'base64'));
  ws.close(); chrome.kill(); process.exit(0);
})();
EOF
timeout 60 node root.js

