package com.gwtplatform.carstore.cucumber.harness;

import org.openqa.selenium.WebDriver;
import org.openqa.selenium.chrome.ChromeDriver;
import org.openqa.selenium.chrome.ChromeOptions;

import com.google.inject.AbstractModule;
import com.google.inject.Guice;
import com.google.inject.Injector;
import com.google.inject.Singleton;
import com.gwtplatform.carstore.cucumber.util.TestParameters;

import cucumber.runtime.java.guice.InjectorSource;

/** Harness glue (not in the provided sources): one headless Chromium driven by the real chromedriver. */
public class WebDriverInjectorSource implements InjectorSource {
    private static WebDriver driver;

    @Override
    public Injector getInjector() {
        return Guice.createInjector(new AbstractModule() {
            @Override
            protected void configure() {
                bind(WebDriver.class).toProvider(() -> driver()).in(Singleton.class);
            }
        });
    }

    static synchronized WebDriver driver() {
        if (driver == null) {
            ChromeOptions options = new ChromeOptions();
            options.setBinary("/usr/bin/chromium");
            options.addArguments("--headless=new", "--no-sandbox", "--disable-gpu", "--disable-dev-shm-usage",
                    "--window-size=1280,900");
            driver = new ChromeDriver(options);
            driver.manage().timeouts().implicitlyWait(0, java.util.concurrent.TimeUnit.SECONDS);
            Runtime.getRuntime().addShutdownHook(new Thread(() -> driver.quit()));
        }
        return driver;
    }
}
