        headerWidgetPage.waitUntilPlaceIsLoaded(MANUFACTURER);
    }

    @Given("^I navigate to the rating page$")
    public void navigateToRating() {
        headerWidgetPage.navigateTo(RATING);
        headerWidgetPage.waitUntilPlaceIsLoaded(RATING);
    }

    @Given("^I navigate to the report page$")
    public void navigateToReport() {
        headerWidgetPage.navigateTo(REPORT);
        headerWidgetPage.waitUntilPlaceIsLoaded(REPORT);
    }
}
